<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO marketing_campaigns(name,objective,channel,status,budget,currency,start_date,end_date) VALUES(?,?,?,?,?,?,?,?)');$q->execute([trim($_POST['name']),trim($_POST['objective']??''),$_POST['channel'],$_POST['status'],(float)($_POST['budget']??0),$_POST['currency']??'USD',$_POST['start_date']?:null,$_POST['end_date']?:null]);header('Location: marketing-campaigns.php');exit;}$rows=$db->query('SELECT * FROM marketing_campaigns ORDER BY created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing Campaigns</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Marketing Campaigns</h1><form method="post" class="card card-body mb-4 row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Campaign name" required></div><div class="col-md-4"><input class="form-control" name="objective" placeholder="Objective"></div><div class="col-md-2"><select class="form-select" name="channel"><option>email</option><option>social</option><option>search</option><option>content</option><option>mixed</option></select></div><div class="col-md-2"><select class="form-select" name="status"><option>draft</option><option>scheduled</option><option>active</option><option>paused</option><option>completed</option></select></div><div class="col-md-3"><input class="form-control" type="number" step="0.01" name="budget" placeholder="Budget"></div><div class="col-md-2"><input class="form-control" name="currency" value="USD"></div><div class="col-md-3"><input class="form-control" type="date" name="start_date"></div><div class="col-md-3"><input class="form-control" type="date" name="end_date"></div><div class="col-12"><button class="btn btn-dark">Create Campaign</button></div></form><div class="card card-body"><table class="table"><thead><tr><th>Name</th><th>Channel</th><th>Status</th><th>Budget</th><th>Dates</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['name'])?></td><td><?=$e($r['channel'])?></td><td><?=$e($r['status'])?></td><td><?=$e($r['currency'].' '.$r['budget'])?></td><td><?=$e($r['start_date'])?> → <?=$e($r['end_date'])?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>